import React, { useEffect, useState } from "react";
import { FaSearch, FaMapMarkerAlt, FaFilter } from "react-icons/fa";
import { Navigation } from "./navigation";
import { useNavigate } from "react-router-dom";
import axios from "axios";
import "../components/css/shops.css";

function Shops() {
  const [shops, setShops] = useState([]);
  const [locations, setLocations] = useState([]);
  const [services, setServices] = useState([]);
  const [selectedLocation, setSelectedLocation] = useState("");
  const [selectedService, setSelectedService] = useState("");
  const [searchQuery, setSearchQuery] = useState("");
  const [debouncedSearchQuery, setDebouncedSearchQuery] = useState("");
  const navigate = useNavigate();
  const [userLocation, setUserLocation] = useState(null);

  useEffect(() => {
    const timer = setTimeout(() => {
      setDebouncedSearchQuery(searchQuery);
    }, 500);
    return () => clearTimeout(timer);
  }, [searchQuery]);

  useEffect(() => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (position) => {
          setUserLocation({
            latitude: position.coords.latitude,
            longitude: position.coords.longitude,
          });
        },
        (error) => console.error("Error getting location:", error)
      );
    } else {
      console.error("Geolocation is not supported by this browser.");
    }
  }, []);

  useEffect(() => {
    const fetchShops = async () => {
      try {
        const response = await axios.get("http://localhost:5000/api/clinics", {
          params: { location: selectedLocation, service: selectedService, search: debouncedSearchQuery },
        });

        console.log("Shops response:", response.data);
        const { clinics = [], locations = [], services = [] } = response.data || {};

        if (!Array.isArray(clinics)) {
          console.error("Clinics data is not an array!", clinics);
          return;
        }

        const activeShops = clinics.filter((shop) => shop.status !== "inactive");

        const shopsWithDistance = activeShops.map((shop) => {
          if (!shop.latitude || !shop.longitude) {
            console.warn(`Skipping shop ${shop.name} due to missing coordinates.`);
            return { ...shop, distance: Infinity };
          }
          return { ...shop, distance: calculateDistance(userLocation, { latitude: shop.latitude, longitude: shop.longitude }) };
        }).sort((a, b) => a.distance - b.distance);

        setShops(shopsWithDistance);
        setLocations(locations);
        setServices(services);
      } catch (error) {
        console.error("Error fetching pet shops:", error);
      }
    };

    if (userLocation) {
      fetchShops();
    }
  }, [selectedLocation, selectedService, debouncedSearchQuery, userLocation]);

  const calculateDistance = (loc1, loc2) => {
    if (!loc1 || !loc2 || isNaN(loc1.latitude) || isNaN(loc1.longitude) || isNaN(loc2.latitude) || isNaN(loc2.longitude)) {
      return Infinity;
    }
    const R = 6371;
    const dLat = (loc2.latitude - loc1.latitude) * (Math.PI / 180);
    const dLon = (loc2.longitude - loc1.longitude) * (Math.PI / 180);
    const a = Math.sin(dLat / 2) ** 2 + Math.cos(loc1.latitude * (Math.PI / 180)) * Math.cos(loc2.latitude * (Math.PI / 180)) * Math.sin(dLon / 2) ** 2;
    return R * (2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a)));
  };

  return <div>/* UI Code remains the same */</div>;
}

export default Shops;
